1	import { Router, type Request } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  DEFAULT_FEEDBACK_DATA_SHARING_TERMS_VERSION,
5	  companyPortabilityExportSchema,
6	  companyPortabilityImportSchema,
7	  companyPortabilityPreviewSchema,
8	  createCompanySchema,
9	  feedbackTargetTypeSchema,
10	  feedbackTraceStatusSchema,
11	  feedbackVoteValueSchema,
12	  updateCompanyBrandingSchema,
13	  updateCompanySchema,
14	} from "@paperclipai/shared";
15	import { badRequest, forbidden } from "../errors.js";
16	import { validate } from "../middleware/validate.js";
17	import {
18	  accessService,
19	  agentService,
20	  budgetService,
21	  companyPortabilityService,
22	  companyService,
23	  feedbackService,
24	  logActivity,
25	} from "../services/index.js";
26	import type { StorageService } from "../storage/types.js";
27	import { assertBoard, assertCompanyAccess, assertInstanceAdmin, getActorInfo } from "./authz.js";
28	
29	export function companyRoutes(db: Db, storage?: StorageService) {
30	  const router = Router();
31	  const svc = companyService(db);
32	  const agents = agentService(db);
33	  const portability = companyPortabilityService(db, storage);
34	  const access = accessService(db);
35	  const budgets = budgetService(db);
36	  const feedback = feedbackService(db);
37	
38	  function parseBooleanQuery(value: unknown) {
39	    return value === true || value === "true" || value === "1";
40	  }
41	
42	  function parseDateQuery(value: unknown, field: string) {
43	    if (typeof value !== "string" || value.trim().length === 0) return undefined;
44	    const parsed = new Date(value);
45	    if (Number.isNaN(parsed.getTime())) {
46	      throw badRequest(`Invalid ${field} query value`);
47	    }
48	    return parsed;
49	  }
50	
51	  function assertImportTargetAccess(
52	    req: Request,
53	    target: { mode: "new_company" } | { mode: "existing_company"; companyId: string },
54	  ) {
55	    if (target.mode === "new_company") {
56	      assertInstanceAdmin(req);
57	      return;
58	    }
59	    assertCompanyAccess(req, target.companyId);
60	  }
61	
62	  async function assertCanUpdateBranding(req: Request, companyId: string) {
63	    assertCompanyAccess(req, companyId);
64	    if (req.actor.type === "board") return;
65	    if (!req.actor.agentId) throw forbidden("Agent authentication required");
66	
67	    const actorAgent = await agents.getById(req.actor.agentId);
68	    if (!actorAgent || actorAgent.companyId !== companyId) {
69	      throw forbidden("Agent key cannot access another company");
70	    }
71	    if (actorAgent.role !== "ceo") {
72	      throw forbidden("Only CEO agents can update company branding");
73	    }
74	  }
75	
76	  async function assertCanManagePortability(req: Request, companyId: string, capability: "imports" | "exports") {
77	    assertCompanyAccess(req, companyId);
78	    if (req.actor.type === "board") return;
79	    if (!req.actor.agentId) throw forbidden("Agent authentication required");
80	
81	    const actorAgent = await agents.getById(req.actor.agentId);
82	    if (!actorAgent || actorAgent.companyId !== companyId) {
83	      throw forbidden("Agent key cannot access another company");
84	    }
85	    if (actorAgent.role !== "ceo") {
86	      throw forbidden(`Only CEO agents can manage company ${capability}`);
87	    }
88	  }
89	
90	  router.get("/", async (req, res) => {
91	    assertBoard(req);
92	    const result = await svc.list();
93	    if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) {
94	      res.json(result);
95	      return;
96	    }
97	    const allowed = new Set(req.actor.companyIds ?? []);
98	    res.json(result.filter((company) => allowed.has(company.id)));
99	  });
100	
101	  router.get("/stats", async (req, res) => {
102	    assertBoard(req);
103	    const allowed = req.actor.source === "local_implicit" || req.actor.isInstanceAdmin
104	      ? null
105	      : new Set(req.actor.companyIds ?? []);
106	    const stats = await svc.stats();
107	    if (!allowed) {
108	      res.json(stats);
109	      return;
110	    }
111	    const filtered = Object.fromEntries(Object.entries(stats).filter(([companyId]) => allowed.has(companyId)));
112	    res.json(filtered);
113	  });
114	
115	  // Common malformed path when companyId is empty in "/api/companies/{companyId}/issues".
116	  router.get("/issues", (_req, res) => {
117	    res.status(400).json({
118	      error: "Missing companyId in path. Use /api/companies/{companyId}/issues.",
119	    });
120	  });
121	
122	  router.get("/:companyId", async (req, res) => {
123	    const companyId = req.params.companyId as string;
124	    assertCompanyAccess(req, companyId);
125	    // Allow agents (CEO) to read their own company; board always allowed
126	    if (req.actor.type !== "agent") {
127	      assertBoard(req);
128	    }
129	    const company = await svc.getById(companyId);
130	    if (!company) {
131	      res.status(404).json({ error: "Company not found" });
132	      return;
133	    }
134	    res.json(company);
135	  });
136	
137	  router.get("/:companyId/feedback-traces", async (req, res) => {
138	    const companyId = req.params.companyId as string;
139	    assertCompanyAccess(req, companyId);
140	    assertBoard(req);
141	
142	    const targetTypeRaw = typeof req.query.targetType === "string" ? req.query.targetType : undefined;
143	    const voteRaw = typeof req.query.vote === "string" ? req.query.vote : undefined;
144	    const statusRaw = typeof req.query.status === "string" ? req.query.status : undefined;
145	    const issueId = typeof req.query.issueId === "string" && req.query.issueId.trim().length > 0 ? req.query.issueId : undefined;
146	    const projectId = typeof req.query.projectId === "string" && req.query.projectId.trim().length > 0
147	      ? req.query.projectId
148	      : undefined;
149	
150	    const traces = await feedback.listFeedbackTraces({
151	      companyId,
152	      issueId,
153	      projectId,
154	      targetType: targetTypeRaw ? feedbackTargetTypeSchema.parse(targetTypeRaw) : undefined,
155	      vote: voteRaw ? feedbackVoteValueSchema.parse(voteRaw) : undefined,
156	      status: statusRaw ? feedbackTraceStatusSchema.parse(statusRaw) : undefined,
157	      from: parseDateQuery(req.query.from, "from"),
158	      to: parseDateQuery(req.query.to, "to"),
159	      sharedOnly: parseBooleanQuery(req.query.sharedOnly),
160	      includePayload: parseBooleanQuery(req.query.includePayload),
161	    });
162	    res.json(traces);
163	  });
164	
165	  router.post("/:companyId/export", validate(companyPortabilityExportSchema), async (req, res) => {
166	    const companyId = req.params.companyId as string;
167	    await assertCanManagePortability(req, companyId, "exports");
168	    const result = await portability.exportBundle(companyId, req.body);
169	    res.json(result);
170	  });
171	
172	  router.post("/import/preview", validate(companyPortabilityPreviewSchema), async (req, res) => {
173	    assertBoard(req);
174	    assertImportTargetAccess(req, req.body.target);
175	    const preview = await portability.previewImport(req.body);
176	    res.json(preview);
177	  });
178	
179	  router.post("/import", validate(companyPortabilityImportSchema), async (req, res) => {
180	    assertBoard(req);
181	    assertImportTargetAccess(req, req.body.target);
182	    const actor = getActorInfo(req);
183	    const result = await portability.importBundle(req.body, req.actor.type === "board" ? req.actor.userId : null);
184	    await logActivity(db, {
185	      companyId: result.company.id,
186	      actorType: actor.actorType,
187	      actorId: actor.actorId,
188	      action: "company.imported",
189	      entityType: "company",
190	      entityId: result.company.id,
191	      agentId: actor.agentId,
192	      runId: actor.runId,
193	      details: {
194	        include: req.body.include ?? null,
195	        agentCount: result.agents.length,
196	        warningCount: result.warnings.length,
197	        companyAction: result.company.action,
198	      },
199	    });
200	    res.json(result);
201	  });
202	
203	  router.post("/:companyId/exports/preview", validate(companyPortabilityExportSchema), async (req, res) => {
204	    const companyId = req.params.companyId as string;
205	    await assertCanManagePortability(req, companyId, "exports");
206	    const preview = await portability.previewExport(companyId, req.body);
207	    res.json(preview);
208	  });
209	
210	  router.post("/:companyId/exports", validate(companyPortabilityExportSchema), async (req, res) => {
211	    const companyId = req.params.companyId as string;
212	    await assertCanManagePortability(req, companyId, "exports");
213	    const result = await portability.exportBundle(companyId, req.body);
214	    res.json(result);
215	  });
216	
217	  router.post("/:companyId/imports/preview", validate(companyPortabilityPreviewSchema), async (req, res) => {
218	    const companyId = req.params.companyId as string;
219	    await assertCanManagePortability(req, companyId, "imports");
220	    if (req.body.target.mode === "existing_company" && req.body.target.companyId !== companyId) {
221	      throw forbidden("Safe import route can only target the route company");
222	    }
223	    if (req.body.collisionStrategy === "replace") {
224	      throw forbidden("Safe import route does not allow replace collision strategy");
225	    }
226	    const preview = await portability.previewImport(req.body, {
227	      mode: "agent_safe",
228	      sourceCompanyId: companyId,
229	    });
230	    res.json(preview);
231	  });
232	
233	  router.post("/:companyId/imports/apply", validate(companyPortabilityImportSchema), async (req, res) => {
234	    const companyId = req.params.companyId as string;
235	    await assertCanManagePortability(req, companyId, "imports");
236	    if (req.body.target.mode === "existing_company" && req.body.target.companyId !== companyId) {
237	      throw forbidden("Safe import route can only target the route company");
238	    }
239	    if (req.body.collisionStrategy === "replace") {
240	      throw forbidden("Safe import route does not allow replace collision strategy");
241	    }
242	    const actor = getActorInfo(req);
243	    const result = await portability.importBundle(req.body, req.actor.type === "board" ? req.actor.userId : null, {
244	      mode: "agent_safe",
245	      sourceCompanyId: companyId,
246	    });
247	    await logActivity(db, {
248	      companyId: result.company.id,
249	      actorType: actor.actorType,
250	      actorId: actor.actorId,
251	      entityType: "company",
252	      entityId: result.company.id,
253	      agentId: actor.agentId,
254	      runId: actor.runId,
255	      action: "company.imported",
256	      details: {
257	        include: req.body.include ?? null,
258	        agentCount: result.agents.length,
259	        warningCount: result.warnings.length,
260	        companyAction: result.company.action,
261	        importMode: "agent_safe",
262	      },
263	    });
264	    res.json(result);
265	  });
266	
267	  router.post("/", validate(createCompanySchema), async (req, res) => {
268	    assertBoard(req);
269	    if (!(req.actor.source === "local_implicit" || req.actor.isInstanceAdmin)) {
270	      throw forbidden("Instance admin required");
271	    }
272	    const company = await svc.create(req.body);
273	    await access.ensureMembership(company.id, "user", req.actor.userId ?? "local-board", "owner", "active");
274	    await logActivity(db, {
275	      companyId: company.id,
276	      actorType: "user",
277	      actorId: req.actor.userId ?? "board",
278	      action: "company.created",
279	      entityType: "company",
280	      entityId: company.id,
281	      details: { name: company.name },
282	    });
283	    if (company.budgetMonthlyCents > 0) {
284	      await budgets.upsertPolicy(
285	        company.id,
286	        {
287	          scopeType: "company",
288	          scopeId: company.id,
289	          amount: company.budgetMonthlyCents,
290	          windowKind: "calendar_month_utc",
291	        },
292	        req.actor.userId ?? "board",
293	      );
294	    }
295	    res.status(201).json(company);
296	  });
297	
298	  router.patch("/:companyId", async (req, res) => {
299	    const companyId = req.params.companyId as string;
300	    assertCompanyAccess(req, companyId);
301	
302	    const actor = getActorInfo(req);
303	    const existingCompany = await svc.getById(companyId);
304	    if (!existingCompany) {
305	      res.status(404).json({ error: "Company not found" });
306	      return;
307	    }
308	    let body: Record<string, unknown>;
309	
310	    if (req.actor.type === "agent") {
311	      // Only CEO agents may update company branding fields
312	      const agentSvc = agentService(db);
313	      const actorAgent = req.actor.agentId ? await agentSvc.getById(req.actor.agentId) : null;
314	      if (!actorAgent || actorAgent.role !== "ceo") {
315	        throw forbidden("Only CEO agents or board users may update company settings");
316	      }
317	      if (actorAgent.companyId !== companyId) {
318	        throw forbidden("Agent key cannot access another company");
319	      }
320	      body = updateCompanyBrandingSchema.parse(req.body);
321	    } else {
322	      assertBoard(req);
323	      body = updateCompanySchema.parse(req.body);
324	
325	      if (body.feedbackDataSharingEnabled === true && !existingCompany.feedbackDataSharingEnabled) {
326	        body = {
327	          ...body,
328	          feedbackDataSharingConsentAt: new Date(),
329	          feedbackDataSharingConsentByUserId: req.actor.userId ?? "local-board",
330	          feedbackDataSharingTermsVersion:
331	            typeof body.feedbackDataSharingTermsVersion === "string" && body.feedbackDataSharingTermsVersion.length > 0
332	              ? body.feedbackDataSharingTermsVersion
333	              : DEFAULT_FEEDBACK_DATA_SHARING_TERMS_VERSION,
334	        };
335	      }
336	    }
337	
338	    const company = await svc.update(companyId, body);
339	    if (!company) {
340	      res.status(404).json({ error: "Company not found" });
341	      return;
342	    }
343	    await logActivity(db, {
344	      companyId,
345	      actorType: actor.actorType,
346	      actorId: actor.actorId,
347	      agentId: actor.agentId,
348	      runId: actor.runId,
349	      action: "company.updated",
350	      entityType: "company",
351	      entityId: companyId,
352	      details: body,
353	    });
354	    res.json(company);
355	  });
356	
357	  router.patch("/:companyId/branding", validate(updateCompanyBrandingSchema), async (req, res) => {
358	    const companyId = req.params.companyId as string;
359	    await assertCanUpdateBranding(req, companyId);
360	    const company = await svc.update(companyId, req.body);
361	    if (!company) {
362	      res.status(404).json({ error: "Company not found" });
363	      return;
364	    }
365	    const actor = getActorInfo(req);
366	    await logActivity(db, {
367	      companyId,
368	      actorType: actor.actorType,
369	      actorId: actor.actorId,
370	      agentId: actor.agentId,
371	      runId: actor.runId,
372	      action: "company.branding_updated",
373	      entityType: "company",
374	      entityId: companyId,
375	      details: req.body,
376	    });
377	    res.json(company);
378	  });
379	
380	  router.post("/:companyId/archive", async (req, res) => {
381	    assertBoard(req);
382	    const companyId = req.params.companyId as string;
383	    assertCompanyAccess(req, companyId);
384	    const company = await svc.archive(companyId);
385	    if (!company) {
386	      res.status(404).json({ error: "Company not found" });
387	      return;
388	    }
389	    await logActivity(db, {
390	      companyId,
391	      actorType: "user",
392	      actorId: req.actor.userId ?? "board",
393	      action: "company.archived",
394	      entityType: "company",
395	      entityId: companyId,
396	    });
397	    res.json(company);
398	  });
399	
400	  router.delete("/:companyId", async (req, res) => {
401	    assertBoard(req);
402	    const companyId = req.params.companyId as string;
403	    assertCompanyAccess(req, companyId);
404	    const company = await svc.remove(companyId);
405	    if (!company) {
406	      res.status(404).json({ error: "Company not found" });
407	      return;
408	    }
409	    res.json({ ok: true });
410	  });
411	
412	  return router;
413	}
